export default async function collectGlaspPages({updatedAfter,accessToken},context) {
  if(typeof accessToken!=='string'||!accessToken.trim()||/[\r\n]/.test(accessToken))throw new Error('Configure a Glasp access token through a secret Variable.');
  if(typeof updatedAfter!=='string'||!Number.isFinite(Date.parse(updatedAfter)))throw new Error('updatedAfter must be a valid timestamp.');
  const pages=[],seen=new Set();
  let cursor=null;
  const deadline=Date.now()+3000000;
  for(let page=0;page<100;page++){
    context.signal?.throwIfAborted();
    const remaining=deadline-Date.now();
    if(remaining<=0)throw new Error('Glasp pagination exceeded its time limit.');
    const url=new URL('https://api.glasp.co/v1/highlights/export');
    url.searchParams.set('updatedAfter',updatedAfter);
    if(cursor!==null)url.searchParams.set('pageCursor',cursor);
    const timeout=AbortSignal.timeout(Math.min(30000,remaining));
    const signal=context.signal?AbortSignal.any([context.signal,timeout]):timeout;
    const response=await context.fetch(url,{method:'GET',headers:{Authorization:'Bearer '+accessToken},signal});
    if(!response.ok)throw new Error('Glasp export failed with HTTP '+response.status+'.');
    const body=await response.json();
    if(!body||typeof body!=='object'||Array.isArray(body)||!Array.isArray(body.results))throw new Error('Glasp export did not return a results array.');
    const next=body.nextPageCursor??null;
    if(next!==null&&typeof next!=='string')throw new Error('Glasp cursor must be text or null.');
    pages.push(body);
    if(!next)return {pages,pageCount:pages.length};
    if(seen.has(next))throw new Error('Glasp repeated a pagination cursor.');
    seen.add(next);cursor=next;
  }
  throw new Error('Glasp has more than 100 pages; tracking has not advanced.');
}

